INSERT INTO questions (question_type, question_text, options, answer, explanation, difficulty, topic, company_tag, role_tag, language, active) VALUES
('CODING','Given a list of employees, use Java Streams to group them by department and return a count per department.','',NULL,'Use Collectors.groupingBy(Employee::getDepartment, Collectors.counting()) on the stream.','Medium','Collections',NULL,'java','Java',1),
('CODING','Implement a thread-safe counter and explain why AtomicInteger outperforms a synchronized int under high contention.','',NULL,'AtomicInteger uses lock-free CAS (compare-and-swap) operations, avoiding the overhead of monitor locks that synchronized requires.','Medium','Concurrency',NULL,'java','Java',1),
('CODING','Design a producer-consumer solution using BlockingQueue in Java.','',NULL,'Use ArrayBlockingQueue or LinkedBlockingQueue; producer threads call put(), consumer threads call take(), which block automatically when full/empty.','Medium','Concurrency',NULL,'java','Java',1),
('CODING','How would you avoid a ConcurrentModificationException when removing elements from a List while iterating over it?','',NULL,'Use an Iterator''s remove() method, or collect items to remove and use removeAll() afterward, or use a CopyOnWriteArrayList for concurrent scenarios.','Easy','Collections',NULL,'java','Java',1),
('CODING','Implement the Singleton pattern in a thread-safe way without synchronizing every call to getInstance().','',NULL,'Use double-checked locking with a volatile instance field, or the initialization-on-demand holder idiom (a static inner class).','Medium','Design Patterns',NULL,'java','Java',1),
('CODING','Given a List<Integer>, use Java Streams to find the sum of squares of only the even numbers.','',NULL,'list.stream().filter(n -> n % 2 == 0).mapToInt(n -> n * n).sum()','Easy','Streams',NULL,'java','Java',1),
('CODING','Implement an LRU cache in Java using LinkedHashMap.','',NULL,'Extend LinkedHashMap with accessOrder=true and override removeEldestEntry() to evict the oldest entry once capacity is exceeded.','Medium','Collections',NULL,'java','Java',1),
('CODING','Explain, with an example, the difference between HashMap and ConcurrentHashMap and when you''d use each.','',NULL,'HashMap is not thread-safe and can corrupt state or infinite-loop under concurrent writes; ConcurrentHashMap uses lock striping for safe concurrent access with better throughput than a synchronized HashMap.','Medium','Collections',NULL,'java','Java',1),
('CODING','Given a list of words, use a dictionary or Counter to find the top 3 most frequent words.','',NULL,'from collections import Counter; Counter(words).most_common(3)','Easy','Dictionaries',NULL,'python','Python',1),
('CODING','Write a generator function that yields Fibonacci numbers infinitely, and explain its memory benefit over building a list.','',NULL,'A generator yields one value at a time and keeps only the current state in memory (O(1) space), unlike a list which stores every value (O(n) space).','Medium','Generators',NULL,'python','Python',1),
('CODING','Write a Python decorator that measures and prints the execution time of any function it wraps.','',NULL,'Use functools.wraps and time.perf_counter() before/after calling the wrapped function inside the decorator''s inner function.','Medium','Decorators',NULL,'python','Python',1),
('CODING','Explain, with a code example, why using threading for a CPU-bound task in Python gives no speedup, and what to use instead.','',NULL,'The GIL allows only one thread to execute Python bytecode at a time, so CPU-bound threads don''t run in parallel. Use multiprocessing to get true parallelism across cores.','Medium','Concurrency',NULL,'python','Python',1),
('CODING','Convert a nested for-loop that flattens a list of lists into a single list comprehension.','',NULL,'[item for sublist in nested_list for item in sublist]','Easy','Comprehensions',NULL,'python','Python',1),
('CODING','Implement a context manager for safely opening and closing a resource using __enter__ and __exit__.','',NULL,'Define a class with __enter__ returning the resource and __exit__ handling cleanup (and exception suppression if needed), or use contextlib.contextmanager with a generator function.','Medium','OOP',NULL,'python','Python',1),
('CODING','Implement a simple LRU cache in Python using OrderedDict.','',NULL,'Use OrderedDict; on access move_to_end(key), and on insert past capacity popitem(last=False) to evict the oldest entry.','Medium','Data Structures',NULL,'python','Python',1),
('CODING','Write an async function using asyncio.gather to run three I/O-bound tasks concurrently.','',NULL,'async def main(): results = await asyncio.gather(task1(), task2(), task3()) — this runs all three coroutines concurrently on the event loop.','Medium','Async',NULL,'python','Python',1),
('CODING','Write a Bash script that finds and deletes log files older than 30 days in /var/log.','',NULL,'find /var/log -name ''*.log'' -type f -mtime +30 -delete','Easy','Bash',NULL,'devops','Bash',1),
('CODING','Write a multi-stage Dockerfile for a Java Spring Boot app that keeps the final image small.','',NULL,'Use one stage with a JDK image to run `mvn package`, then COPY only the built JAR into a slim JRE-only final stage, discarding build tools and source from the final image.','Medium','Docker',NULL,'devops','Docker',1),
('CODING','Write a Kubernetes Deployment manifest with 3 replicas, resource limits, and a readiness probe for a web service.','',NULL,'Set spec.replicas: 3, define resources.limits (cpu/memory), and add readinessProbe with an httpGet path/port so traffic only routes to ready pods.','Medium','Kubernetes',NULL,'devops','YAML',1),
('CODING','Write a GitHub Actions workflow that runs tests on every PR and deploys to production only on merges to main.','',NULL,'Use two jobs: a test job triggered on pull_request, and a deploy job triggered on push to main with an `if: github.ref == ''refs/heads/main''` condition.','Medium','CI/CD',NULL,'devops','YAML',1),
('CODING','A Terraform apply fails with ''resource already exists''. How do you resolve it without breaking existing infrastructure?','',NULL,'Use `terraform import` to bring the existing resource into state instead of recreating it, then run `terraform plan` to confirm no unwanted changes.','Medium','Terraform',NULL,'devops','HCL',1),
('CODING','Write a Python script using boto3 to list all EC2 instances that have been running for more than 7 days.','',NULL,'Use boto3.client(''ec2'').describe_instances(), then compare each instance''s LaunchTime to datetime.now(timezone.utc) - timedelta(days=7).','Medium','Automation',NULL,'devops','Python',1),
('CODING','Write a Prometheus alerting rule that fires when CPU usage is above 90% for more than 5 minutes.','',NULL,'expr: 100 - (avg by(instance)(rate(node_cpu_seconds_total{mode=''idle''}[5m])) * 100) > 90, with `for: 5m` in the alert rule.','Medium','Monitoring',NULL,'devops','YAML',1),
('CODING','Write a script that rotates and compresses log files, keeping only the last 7 days.','',NULL,'Use logrotate with `rotate 7`, `compress`, and `daily` directives, or a custom find+gzip script combined with mtime-based deletion.','Easy','Bash',NULL,'devops','Bash',1),
('CODING','Write a SQL query using a window function to find the top 3 highest-paid employees per department.','',NULL,'Use RANK() OVER (PARTITION BY department ORDER BY salary DESC) in a subquery/CTE, then filter WHERE rank <= 3.','Medium','SQL',NULL,'data-engineer','SQL',1),
('CODING','Write a SQL query to find duplicate rows based on multiple columns and delete all but one copy.','',NULL,'Use ROW_NUMBER() OVER (PARTITION BY col1, col2 ORDER BY id) in a CTE, then DELETE WHERE row_number > 1.','Medium','SQL',NULL,'data-engineer','SQL',1),
('CODING','Write PySpark code to read a CSV, filter out rows where a column is null, and write the result as Parquet partitioned by date.','',NULL,'df = spark.read.csv(path, header=True); df.filter(df.col.isNotNull()).write.partitionBy(''date'').parquet(output_path)','Medium','PySpark',NULL,'data-engineer','Python',1),
('CODING','An Airflow DAG fails intermittently on one task. Walk through how you''d debug it.','',NULL,'Check task logs for the failing run, review retry/backoff config, check for resource contention or upstream data timing issues, and consider adding sensors or SLAs to catch it earlier.','Medium','ETL',NULL,'data-engineer','Python',1),
('CODING','Describe how a Kafka consumer can process messages exactly once, including offset commit strategy.','',NULL,'Disable auto-commit, process the message, write results and commit the offset atomically (e.g. in the same DB transaction, or using Kafka transactions/idempotent producers).','Hard','Streaming',NULL,'data-engineer','Any',1),
('CODING','Write a Python function that validates a Pandas DataFrame has no nulls in required columns and no duplicate primary keys.','',NULL,'Check df[required_cols].isnull().sum() == 0 and df[pk_cols].duplicated().sum() == 0, raising a descriptive ValueError on violation.','Medium','Data Quality',NULL,'data-engineer','Python',1),
('CODING','Write a SQL query to pivot monthly sales rows into separate columns per month.','',NULL,'Use conditional aggregation: SUM(CASE WHEN month = ''Jan'' THEN sales END) AS jan_sales, repeated per month, GROUP BY product.','Medium','SQL',NULL,'data-engineer','SQL',1),
('CODING','Given a JSON file with nested arrays, write PySpark code to flatten it into a tabular DataFrame.','',NULL,'Use df.select(explode(col(''nested_array'')).alias(''item'')) combined with selecting nested fields, repeating explode for multiple nesting levels.','Medium','Schema',NULL,'data-engineer','Python',1),
('CODING','Write a Selenium script that waits explicitly for an element to be clickable before clicking it.','',NULL,'Use WebDriverWait with ExpectedConditions.elementToBeClickable(locator) instead of Thread.sleep(), so the click only happens once the element is ready.','Easy','Selenium',NULL,'testing','Java',1),
('CODING','Write an API test that verifies a POST /users endpoint returns 201 and the correct Location header.','',NULL,'Using RestAssured: given().body(payload).post(''/users'').then().statusCode(201).header(''Location'', containsString(''/users/''))','Medium','API Testing',NULL,'testing','Java',1),
('CODING','Design a Page Object class for a login page with methods for entering credentials and submitting.','',NULL,'Encapsulate locators as fields and expose methods like enterUsername(), enterPassword(), and submit(), keeping test code free of raw selectors.','Easy','Automation Framework',NULL,'testing','Java',1),
('CODING','Write a failing unit test first, then the minimal code to make it pass, for a function that validates email format.','',NULL,'Red-Green-Refactor: write assertFalse(isValidEmail(''bad'')) and assertTrue(isValidEmail(''a@b.com'')) first, then implement isValidEmail with a regex check.','Easy','TDD',NULL,'testing','Any',1),
('CODING','Write a test that mocks an external payment API call so the test doesn''t depend on network availability.','',NULL,'Use a mocking framework (e.g. Mockito/WireMock) to stub the payment client''s response, isolating the test from the real network call.','Medium','Mocking',NULL,'testing','Java',1),
('CODING','A test fails intermittently due to a race condition with an async page load. Diagnose and fix it.','',NULL,'Replace fixed sleeps with explicit waits for a specific DOM condition or network idle state, and verify the app itself isn''t the source of nondeterminism.','Medium','Flaky Tests',NULL,'testing','Any',1),
('CODING','Write a CI configuration that runs a test suite in parallel across 4 shards.','',NULL,'Use a matrix strategy (e.g. GitHub Actions `strategy.matrix.shard: [1,2,3,4]`) with the test runner''s built-in sharding flag (e.g. --shard=1/4).','Medium','CI Integration',NULL,'testing','YAML',1),
('CODING','Write a data-driven test that runs the same login test with 5 different sets of credentials from a CSV file.','',NULL,'Use a parameterized test annotation (e.g. JUnit''s @CsvFileSource or pytest''s @pytest.mark.parametrize) to iterate over the CSV rows, reusing one test method.','Easy','Data-Driven Testing',NULL,'testing','Any',1);
INSERT INTO questions (question_type, question_text, options, answer, explanation, difficulty, topic, company_tag, role_tag, language, active) VALUES
('SYSTEM_DESIGN','Design a URL Shortener.','',NULL,'Focus on the hashing/encoding scheme for short codes, the DB schema, and how you''d scale reads (caching, read replicas).','Medium','System Design',NULL,'java',NULL,1),
('SYSTEM_DESIGN','Design an E-commerce Checkout & Payment Flow.','',NULL,'Cover idempotency keys to avoid double-charging, and how distributed transactions/sagas keep inventory and payment in sync.','Medium','System Design',NULL,'java',NULL,1),
('SYSTEM_DESIGN','Design a Rate Limiter.','',NULL,'Compare token bucket vs sliding window algorithms, and how you''d implement it with Redis for a distributed service.','Medium','System Design',NULL,'java',NULL,1),
('SYSTEM_DESIGN','Design a Notification System (push/email/SMS).','',NULL,'Cover fan-out to multiple channels, retry/backoff on failed delivery, and using queues to decouple senders from producers.','Medium','System Design',NULL,'java',NULL,1),
('SYSTEM_DESIGN','Design a Distributed Cache.','',NULL,'Cover consistent hashing for node distribution and eviction policies (LRU/LFU) for memory management.','Medium','System Design',NULL,'java',NULL,1),
('SYSTEM_DESIGN','Design a Distributed Job Scheduler.','',NULL,'Cover leader election so only one node triggers a given job, and distributed locks to prevent duplicate execution.','Medium','System Design',NULL,'java',NULL,1),
('SYSTEM_DESIGN','Design the communication pattern between microservices for an order-processing system.','',NULL,'Compare synchronous REST calls vs async messaging, and explain how the Saga pattern handles distributed transactions across services.','Medium','System Design',NULL,'java',NULL,1),
('SYSTEM_DESIGN','Design a Web Crawler.','',NULL,'Cover politeness policies (robots.txt, rate limiting per domain), deduplication of URLs, and a distributed frontier queue.','Medium','System Design',NULL,'python',NULL,1),
('SYSTEM_DESIGN','Design a Recommendation System.','',NULL,'Compare collaborative filtering vs content-based approaches, and discuss offline batch scoring vs online real-time serving.','Medium','System Design',NULL,'python',NULL,1),
('SYSTEM_DESIGN','Design a Real-time Chat Application.','',NULL,'Cover WebSocket connections, message ordering guarantees, and how you''d track user presence.','Medium','System Design',NULL,'python',NULL,1),
('SYSTEM_DESIGN','Design a URL Shortener.','',NULL,'Focus on the hashing scheme, DB schema, and read scaling via caching.','Medium','System Design',NULL,'python',NULL,1),
('SYSTEM_DESIGN','Design a Rate Limiter for an API Gateway.','',NULL,'Compare token bucket vs sliding window, and how limits are enforced per-user vs per-IP.','Medium','System Design',NULL,'python',NULL,1),
('SYSTEM_DESIGN','Design an ML Model Serving Pipeline.','',NULL,'Compare batch vs real-time inference, and the role of a feature store in keeping training/serving features consistent.','Medium','System Design',NULL,'python',NULL,1),
('SYSTEM_DESIGN','Design a Data Pipeline for Analytics.','',NULL,'Compare batch ETL vs streaming ingestion, and how you''d handle late-arriving data.','Medium','System Design',NULL,'python',NULL,1),
('SYSTEM_DESIGN','Design a CI/CD Pipeline for a Microservices Platform.','',NULL,'Cover build/test/deploy stages, artifact promotion across environments, and a rollback strategy.','Medium','System Design',NULL,'devops',NULL,1),
('SYSTEM_DESIGN','Design a Multi-Region, Highly Available Kubernetes Architecture.','',NULL,'Cover cluster federation or active-active regions, cross-region data replication, and failover.','Medium','System Design',NULL,'devops',NULL,1),
('SYSTEM_DESIGN','Design a Centralized Logging & Monitoring System.','',NULL,'Cover log aggregation (ELK) or metrics (Prometheus+Grafana), and how alerting rules are structured to avoid noise.','Medium','System Design',NULL,'devops',NULL,1),
('SYSTEM_DESIGN','Design a Blue-Green / Canary Deployment Strategy.','',NULL,'Cover traffic-shifting mechanics, health-check gating, and automated rollback on error-rate spikes.','Medium','System Design',NULL,'devops',NULL,1),
('SYSTEM_DESIGN','Design a Secrets Management & Access Control System.','',NULL,'Cover a secrets store (e.g. Vault), least-privilege IAM policies, and secret rotation.','Medium','System Design',NULL,'devops',NULL,1),
('SYSTEM_DESIGN','Design an Auto-scaling Infrastructure.','',NULL,'Cover metrics-based scaling policies (CPU/queue depth) and cost-optimization tradeoffs (spot instances, scale-to-zero).','Medium','System Design',NULL,'devops',NULL,1),
('SYSTEM_DESIGN','Design a Disaster Recovery & Backup Strategy for cloud infrastructure.','',NULL,'Cover RTO/RPO tradeoffs and how backup frequency/location choices map to recovery guarantees.','Medium','System Design',NULL,'devops',NULL,1),
('SYSTEM_DESIGN','Design a Data Warehouse / Lakehouse architecture.','',NULL,'Compare star schema vs data vault modeling, and discuss partitioning strategy for query performance.','Medium','System Design',NULL,'data-engineer',NULL,1),
('SYSTEM_DESIGN','Design a Real-time Streaming Pipeline.','',NULL,'Cover Kafka → Spark/Flink → sink architecture and how exactly-once semantics are achieved.','Medium','System Design',NULL,'data-engineer',NULL,1),
('SYSTEM_DESIGN','Design a Batch ETL Orchestration system.','',NULL,'Cover Airflow DAG design, task dependency management, and how backfills are handled safely.','Medium','System Design',NULL,'data-engineer',NULL,1),
('SYSTEM_DESIGN','Design a Data Lake with governance.','',NULL,'Cover a schema registry, access control at the dataset level, and a data catalog for discoverability.','Medium','System Design',NULL,'data-engineer',NULL,1),
('SYSTEM_DESIGN','Design a Change Data Capture (CDC) pipeline.','',NULL,'Cover a Debezium-style log-based approach and how schema drift from the source is handled downstream.','Medium','System Design',NULL,'data-engineer',NULL,1),
('SYSTEM_DESIGN','Design a Feature Store for ML pipelines.','',NULL,'Cover keeping training and serving features consistent, and handling both batch and low-latency online lookups.','Medium','System Design',NULL,'data-engineer',NULL,1),
('SYSTEM_DESIGN','Design a Data Pipeline Monitoring & Alerting system.','',NULL,'Cover data freshness SLAs and volume anomaly detection to catch silent pipeline failures.','Medium','System Design',NULL,'data-engineer',NULL,1),
('SYSTEM_DESIGN','Design a Test Automation Framework.','',NULL,'Compare Page Object Model, data-driven, and keyword-driven architectures, and when each fits.','Medium','System Design',NULL,'testing',NULL,1),
('SYSTEM_DESIGN','Design a Continuous Testing pipeline.','',NULL,'Cover parallel execution and test sharding strategy to keep CI/CD pipelines fast.','Medium','System Design',NULL,'testing',NULL,1),
('SYSTEM_DESIGN','Design a Test Data Management system.','',NULL,'Cover synthetic data generation and masking production-like data safely for lower environments.','Medium','System Design',NULL,'testing',NULL,1),
('SYSTEM_DESIGN','Design a Performance/Load Testing strategy.','',NULL,'Cover tooling choices (JMeter/Gatling), identifying bottlenecks, and scaling the load-generation infrastructure itself.','Medium','System Design',NULL,'testing',NULL,1),
('SYSTEM_DESIGN','Design a Bug Tracking & Triage workflow for a large multi-team org.','',NULL,'Cover severity/priority frameworks and how triage routes issues to the right team quickly.','Medium','System Design',NULL,'testing',NULL,1),
('SYSTEM_DESIGN','Design a Cross-browser/Cross-device Testing strategy.','',NULL,'Cover device farms, cloud testing grids, and how you''d prioritize coverage given limited time.','Medium','System Design',NULL,'testing',NULL,1),
('SYSTEM_DESIGN','Design a Test Coverage & Quality Metrics dashboard.','',NULL,'Cover tracking flakiness over time and surfacing coverage gaps to the team.','Medium','System Design',NULL,'testing',NULL,1);
